import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Save, Trash2, Menu, X, User, LogOut, Plus, Search, Settings, Archive, Trash } from 'lucide-react';
import axios from 'axios';

const API_URL = 'http://localhost:5001';

function App() {
  const [notes, setNotes] = useState([]);
  const [activeTab, setActiveTab] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('googleToken');
    if (token) {
      setIsAuthenticated(true);
      fetchNotes();
    }
    setIsLoading(false);
  }, []);

  const handleAuthCallback = useCallback(async () => {
    const urlParams = new URLSearchParams(window.location.search);
    const tokens = urlParams.get('tokens');
    const error = urlParams.get('error');

    if (error) {
      console.error('Auth error:', error);
      return;
    }

    if (tokens) {
      try {
        const parsedTokens = JSON.parse(decodeURIComponent(tokens));
        localStorage.setItem('googleToken', JSON.stringify(parsedTokens));
        setIsAuthenticated(true);
        fetchNotes();
        window.history.replaceState({}, document.title, '/');
      } catch (error) {
        console.error('Error parsing tokens:', error);
      }
    }
  }, []);

  useEffect(() => {
    handleAuthCallback();
  }, [handleAuthCallback]);

  const handleGoogleLogin = async () => {
    window.location.href = `${API_URL}/auth/google`;
  };

  const fetchNotes = async () => {
    try {
      const token = localStorage.getItem('googleToken');
      const response = await axios.get(`${API_URL}/api/notes`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNotes(response.data);
      if (response.data.length > 0 && !activeTab) {
        setActiveTab(response.data[0].id);
      }
    } catch (error) {
      console.error('Error fetching notes:', error);
    }
  };

  const handleContentChange = async (content) => {
    if (!activeTab) return;
    try {
      const token = localStorage.getItem('googleToken');
      await axios.put(`${API_URL}/api/notes/${activeTab}`, { content }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNotes(notes.map(note => 
        note.id === activeTab ? { ...note, content } : note
      ));
    } catch (error) {
      console.error('Error updating note:', error);
    }
  };

  const addNewNote = async () => {
    try {
      const token = localStorage.getItem('googleToken');
      const response = await axios.post(`${API_URL}/api/notes`, { content: '' }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNotes([...notes, response.data]);
      setActiveTab(response.data.id);
    } catch (error) {
      console.error('Error creating note:', error);
    }
  };

  const deleteNote = async () => {
    if (!activeTab) return;
    try {
      const token = localStorage.getItem('googleToken');
      await axios.delete(`${API_URL}/api/notes/${activeTab}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      const newNotes = notes.filter(note => note.id !== activeTab);
      setNotes(newNotes);
      if (newNotes.length > 0) {
        setActiveTab(newNotes[0].id);
      } else {
        setActiveTab(null);
      }
    } catch (error) {
      console.error('Error deleting note:', error);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('googleToken');
    setIsAuthenticated(false);
    setNotes([]);
    setActiveTab(null);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen w-full flex items-center justify-center bg-black">
        <motion.div
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{
            type: "spring",
            stiffness: 260,
            damping: 20,
            duration: 0.6,
          }}
          className="animate-float"
        >
          <div className="relative">
            <h1 className="text-6xl font-bold text-white">
              Clea<span className="text-purple-500 animate-pulse-glow">Note</span>
            </h1>
            <div className="absolute -inset-2 bg-purple-500/20 blur-xl rounded-full -z-10"></div>
          </div>
        </motion.div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen w-full flex flex-col items-center justify-center bg-black p-4">
        <div className="w-full max-w-md mx-auto flex flex-col items-center">
          <motion.div
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{
              type: "spring",
              stiffness: 260,
              damping: 20,
              duration: 0.6,
            }}
            className="mb-8 animate-float"
          >
            <div className="relative">
              <h1 className="text-6xl font-bold text-white">
                Clea<span className="text-purple-500 animate-pulse-glow">Note</span>
              </h1>
              <div className="absolute -inset-2 bg-purple-500/20 blur-xl rounded-full -z-10"></div>
            </div>
            <p className="text-purple-300 text-center mt-2 animate-fade-in">Minimal. Beautiful. Focused.</p>
          </motion.div>

          <motion.div
            initial={{ y: 50, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ delay: 0.3, duration: 0.5 }}
            className="w-full animate-slide-in"
          >
            <div className="bg-zinc-900/70 backdrop-blur-lg p-8 rounded-2xl shadow-xl border border-purple-500/20 relative">
              <div className="absolute -inset-0.5 bg-gradient-to-r from-purple-500 to-pink-500 rounded-2xl blur opacity-20 -z-10 animate-pulse-glow"></div>

              <h2 className="text-2xl font-bold text-white mb-6 text-center animate-fade-in">Welcome Back</h2>

              <div className="space-y-6">
                <button
                  onClick={handleGoogleLogin}
                  className="w-full relative overflow-hidden group border border-purple-500/30 hover:border-purple-500 bg-zinc-900/50 text-white hover:text-white hover:bg-zinc-800 rounded-lg px-4 py-2 flex items-center justify-center gap-3 transition-all duration-300 ease-bounce-in"
                >
                  <div className="absolute inset-0 bg-gradient-to-r from-purple-500/10 to-pink-500/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                  <svg viewBox="0 0 24 24" className="w-5 h-5">
                    <path
                      fill="currentColor"
                      d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                    />
                    <path
                      fill="currentColor"
                      d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                    />
                    <path
                      fill="currentColor"
                      d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                    />
                    <path
                      fill="currentColor"
                      d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                    />
                  </svg>
                  Sign in with Google
                </button>
              </div>

              <div className="mt-8 text-center text-xs text-zinc-400 animate-fade-in">
                By continuing, you agree to CleaNote's
                <br />
                Terms of Service and Privacy Policy
              </div>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.8 }}
            className="mt-8 text-purple-300/50 text-sm text-center animate-fade-in"
          >
            The simplest way to capture your thoughts.
          </motion.div>
        </div>
      </div>
    );
  }

  const activeNote = notes.find(note => note.id === activeTab);
  const filteredNotes = notes.filter(note => 
    note.content.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="flex h-screen bg-black text-white">
      {/* Sidebar */}
      <AnimatePresence>
        {sidebarOpen && (
          <motion.div
            initial={{ x: -300, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: -300, opacity: 0 }}
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
            className="w-80 border-r border-zinc-800 bg-zinc-900/50 backdrop-blur-lg"
          >
            <div className="p-4">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold text-white">Notes</h2>
                <button
                  onClick={addNewNote}
                  className="p-2 hover:bg-zinc-800 rounded-lg transition-colors"
                >
                  <Plus className="w-5 h-5" />
                </button>
              </div>

              <div className="relative mb-4">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-zinc-400" />
                <input
                  type="text"
                  placeholder="Search notes..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 bg-zinc-800/50 border border-zinc-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50"
                />
              </div>

              <div className="space-y-2">
                {filteredNotes.map(note => (
                  <button
                    key={note.id}
                    onClick={() => {
                      setActiveTab(note.id);
                      setSidebarOpen(false);
                    }}
                    className={`w-full text-left p-3 rounded-lg transition-colors ${
                      activeTab === note.id
                        ? 'bg-purple-500/20 border border-purple-500/30'
                        : 'hover:bg-zinc-800/50'
                    }`}
                  >
                    <div className="text-sm font-medium truncate">
                      {note.content.split('\n')[0] || 'Untitled'}
                    </div>
                    <div className="text-xs text-zinc-400 mt-1">
                      {new Date(note.createdTime).toLocaleDateString()}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Main Content */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <header className="h-16 border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-lg flex items-center justify-between px-4">
          <div className="flex items-center space-x-4">
            <button
              onClick={() => setSidebarOpen(!sidebarOpen)}
              className="p-2 hover:bg-zinc-800 rounded-lg transition-colors"
            >
              <Menu className="w-5 h-5" />
            </button>
            <h1 className="text-xl font-bold">CleaNote</h1>
          </div>

          <div className="flex items-center space-x-2">
            <button
              onClick={deleteNote}
              className="p-2 hover:bg-zinc-800 rounded-lg transition-colors"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <button
              onClick={handleLogout}
              className="p-2 hover:bg-zinc-800 rounded-lg transition-colors"
            >
              <LogOut className="w-5 h-5" />
            </button>
          </div>
        </header>

        {/* Editor */}
        <div className="flex-1 p-4">
          <AnimatePresence mode="wait">
            {activeNote ? (
              <motion.div
                key={activeNote.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.2 }}
                className="h-full"
              >
                <textarea
                  value={activeNote.content}
                  onChange={(e) => handleContentChange(e.target.value)}
                  className="w-full h-full p-4 bg-zinc-900/50 border border-zinc-800 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50 resize-none"
                  placeholder="Start writing..."
                />
              </motion.div>
            ) : (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="h-full flex items-center justify-center text-zinc-400"
              >
                Select a note or create a new one
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}

export default App;
